```cpp
#include <bits/stdc++.h>
using namespace std;


vector<long long> solve_case(int n, int d, const vector<long long>& arr) {
    vector<vector<long long>> groups(d);

    // 按下标模 d 分组
    for (int i = 0; i < n; i++) {
        groups[i % d].push_back(arr[i]);
    }

    // 每组降序排序
    for (int i = 0; i < d; i++) {
        sort(groups[i].begin(), groups[i].end(), greater<long long>());
    }

    vector<int> idx(d, 0);
    vector<long long> res(n);

    // 按位置顺序回填
    for (int i = 0; i < n; i++) {
        int g = i % d;
        res[i] = groups[g][idx[g]];
        idx[g]++;
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, d;
        cin >> n >> d;

        vector<long long> arr(n);
        for (int i = 0; i < n; i++) {
            cin >> arr[i];
        }

        vector<long long> res = solve_case(n, d, arr);

        for (int i = 0; i < n; i++) {
            if (i) cout << ' ';
            cout << res[i];
        }
        cout << '\n';
    }

    return 0;
}
